"use strict";(globalThis.webpackChunkncds_admin_docs=globalThis.webpackChunkncds_admin_docs||[]).push([[31478],{72477(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"release-note-editor-0.2.1","metadata":{"permalink":"/design-system/ncds-admin/releases/editor/release-note-editor-0.2.1","source":"@site/blog-editor/v0.2.1.md","title":"v0.2.1","description":"Editor \ub9b4\ub9ac\uc988 \ub178\ud2b8 (v0.2.1)","date":"2026-04-27T00:00:00.000Z","tags":[{"inline":false,"label":"Editor","permalink":"/design-system/ncds-admin/releases/editor/tags/editor","description":"Editor tag description"},{"inline":false,"label":"Improvement","permalink":"/design-system/ncds-admin/releases/editor/tags/improvement","description":"Improvement tag description"},{"inline":true,"label":"security","permalink":"/design-system/ncds-admin/releases/editor/tags/security"}],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"release-note-editor-0.2.1","title":"v0.2.1","date":"2026-04-27","tags":["editor","improvement","security"]},"unlisted":false,"nextItem":{"title":"v0.2.0","permalink":"/design-system/ncds-admin/releases/editor/release-note-editor-0.2.0"}},"content":"## Editor \ub9b4\ub9ac\uc988 \ub178\ud2b8 (v0.2.1)\\n\\n### \uc2e0\uaddc \uae30\ub2a5\\n\\n- **\ubc18\uc751\ud615 \ud234\ubc14**: \ucee8\ud14c\uc774\ub108 \ub108\ube44\uc5d0 \ub530\ub77c XS / SM / MD / DEFAULT 4\ub2e8\uacc4 \ud234\ubc14 \uad6c\uc131\uc744 \uc790\ub3d9\uc73c\ub85c \uc120\ud0dd\ud569\ub2c8\ub2e4.\\n  - 768 / 992 / 1200px \ube0c\ub808\uc774\ud06c\ud3ec\uc778\ud2b8 \uae30\ubc18\\n  - \ub9c8\uc6b4\ud2b8 \uc2dc\uc810\uc5d0 \ucee8\ud14c\uc774\ub108 \ub108\ube44\ub97c \uce21\uc815\ud574 \uc801\uc808\ud55c \uad6c\uc131\uc744 \uc801\uc6a9\ud569\ub2c8\ub2e4.\\n- **CommerceSans \ud3f0\ud2b8 \uc9c0\uc6d0**: \ud3f0\ud2b8 \uc815\uc758(@font-face 3 weights)\uc640 \ud3f0\ud2b8 \ud328\ubc00\ub9ac \uc635\uc158\uc744 \ucd94\uac00\ud558\uc600\uc2b5\ub2c8\ub2e4.\\n\\n### \uae30\ub2a5 \uac1c\uc120\\n\\n- **\uc544\uc774\ucf58 \uc801\uc6a9 \ubc29\uc2dd \ubcc0\uacbd**: Froala \uacf5\uc2dd `DefineIcon` API\ub85c NCDS \uc544\uc774\ucf58\uc744 \ub4f1\ub85d\ud558\ub3c4\ub85d \ubcc0\uacbd\ud558\uc600\uc2b5\ub2c8\ub2e4.\\n  - Froala \ub0b4\ubd80 \uc7ac\ub80c\ub354 \uc2dc\uc5d0\ub3c4 \uc544\uc774\ucf58\uc774 \uc6d0\ubcf5\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n  - iframe / non-iframe \ubaa8\ub4dc \ubaa8\ub450\uc5d0\uc11c \uc77c\uad00\ub418\uac8c \uc801\uc6a9\ub429\ub2c8\ub2e4.\\n  - \ub204\ub77d\ub418\uc5b4 \uc788\ub358 \uc544\uc774\ucf58 9\uc885\uc744 \ubcf4\uac15\ud558\uc600\uc2b5\ub2c8\ub2e4 (`alignLeft`, `alignCenter`, `alignRight`, `alignJustify`, `outdent`, `indent`, `subscript`, `paragraphFormat`, `pastePlain`).\\n- **iframe \uc2a4\ud0c0\uc77c \ud1b5\uc77c**: \ubcf8\ubb38 \ud3f0\ud2b8(\ub098\ub214\uace0\ub515), \ud589\uac04, `<p>` \uc5ec\ubc31, NCDS \uc5d0\ub514\ud130 CDN CSS\ub97c iframe \ub0b4\ubd80\uc5d0 \uc8fc\uc785\ud558\ub3c4\ub85d \ubcf4\uc644\ud558\uc600\uc2b5\ub2c8\ub2e4.\\n- **\ud3ec\ucee4\uc2a4 \uadf8\ub9bc\uc790 \ubcf4\uc7a5**: `fr-focused` \ud074\ub798\uc2a4\ub97c focus/blur \uc774\ubca4\ud2b8\uc5d0\uc11c \uc218\ub3d9 \uad00\ub9ac\ud558\uc5ec iframe\xb7non-iframe \ubaa8\ub4dc \ubaa8\ub450\uc5d0\uc11c \ud3ec\ucee4\uc2a4 \uc2dc \uadf8\ub9bc\uc790\uac00 \uc815\uc0c1\uc801\uc73c\ub85c \ud45c\uc2dc\ub429\ub2c8\ub2e4.\\n- **\ucf58\ud150\uce20 \ud3ed \uc81c\ud55c\xb7\uc904\ubc14\uafc8**: \ud328\ub110 320px / content 296px \ucd5c\ub300 \ub108\ube44\uc640 \ud55c\uae00 \uc5b4\uc808 \ub2e8\uc704 \uc904\ubc14\uafc8(`word-break: keep-all`)\uc744 \uc801\uc6a9\ud558\uc600\uc2b5\ub2c8\ub2e4.\\n- **\ud234\ubc14 \uad6c\uc131 \uc815\ub82c**: HTML \ubc84\uc804\uacfc \ub3d9\uc77c\ud55c \uae30\ubcf8 \ud234\ubc14 \uad6c\uc131\uc744 \uc0ac\uc6a9\ud558\ub3c4\ub85d \uc815\ub9ac\ud558\uc600\uc2b5\ub2c8\ub2e4.\\n- **\ud55c\uad6d\uc5b4 \ubc88\uc5ed \uc815\ub9ac**: \ubc88\uc5ed \ud30c\uc77c(`languages/ko.ts`)\uc758 \uc5b4\uc0c9\ud55c \ubb38\uad6c\ub97c \uc790\uc5f0\uc2a4\ub7fd\uac8c \ub2e4\ub4ec\uc5c8\uc73c\uba70, \ub2e8\ub77d \ud3ec\ub9f7 \ub77c\ubca8 `Code`\ub97c \uc2e4\uc81c \ucd9c\ub825 \ud0dc\uadf8\uc640 \uc77c\uce58\ud558\ub3c4\ub85d `pre`\ub85c \ubcc0\uacbd\ud558\uc600\uc2b5\ub2c8\ub2e4.\\n\\n### \ubcf4\uc548\\n\\n- **HTML \ud544\ud130\ub9c1 \uac15\ud654**\\n  - `htmlAllowedTags`\ub97c \uba85\uc2dc\ud574 Froala \uae30\ubcf8 \ud5c8\uc6a9 \ud0dc\uadf8 \uc911 \uc704\ud5d8 \ud0dc\uadf8\ub97c \uc81c\uc678\ud558\uc600\uc2b5\ub2c8\ub2e4.\\n    - \uc81c\uac70 \ub300\uc0c1: `script`, `base`, `bdo`, `dialog`, `keygen`, `menuitem`, `noscript`, `queue`, `title`, SVG \uacc4\uc5f4\\n    - \ubc18\uc751\ud615 \uc774\ubbf8\uc9c0 `<picture>`\ub294 \ubcc4\ub3c4\ub85c \ud5c8\uc6a9 \ubaa9\ub85d\uc5d0 \ucd94\uac00\ud558\uc600\uc2b5\ub2c8\ub2e4.\\n  - `htmlRemoveTags`\ub97c \ucd94\uac00\ud574 \uc704\ud5d8 \ud0dc\uadf8\ub97c \ud0dc\uadf8\xb7\ub0b4\uc6a9 \ubaa8\ub450 \uc644\uc804 \uc81c\uac70\ud569\ub2c8\ub2e4."},{"id":"release-note-editor-0.2.0","metadata":{"permalink":"/design-system/ncds-admin/releases/editor/release-note-editor-0.2.0","source":"@site/blog-editor/v0.2.0.md","title":"v0.2.0","description":"Editor \ub9b4\ub9ac\uc988 \ub178\ud2b8 (v0.2.0)","date":"2026-03-17T00:00:00.000Z","tags":[{"inline":false,"label":"Editor","permalink":"/design-system/ncds-admin/releases/editor/tags/editor","description":"Editor tag description"},{"inline":false,"label":"Improvement","permalink":"/design-system/ncds-admin/releases/editor/tags/improvement","description":"Improvement tag description"}],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"release-note-editor-0.2.0","title":"v0.2.0","date":"2026-03-17","tags":["editor","improvement"]},"unlisted":false,"prevItem":{"title":"v0.2.1","permalink":"/design-system/ncds-admin/releases/editor/release-note-editor-0.2.1"},"nextItem":{"title":"v1.0.0","permalink":"/design-system/ncds-admin/releases/editor/release-note-editor-0.1.0"}},"content":"## Editor \ub9b4\ub9ac\uc988 \ub178\ud2b8 (v0.2.0)\\n\\n### \uac1c\uc120\\n\\n- NCDS Editor React \ubc84\uc804\uc758 \ucee4\uc2a4\ud140 \uc2a4\ud0c0\uc77c\uc744 NCDS \uac00\uc774\ub4dc\uc5d0 \ub9de\ucdb0 \uc5c5\ub370\uc774\ud2b8\ud558\uc600\uc2b5\ub2c8\ub2e4.\\n- \uae30\ubcf8 \ucee8\ud14c\uc774\ub108 \ud074\ub798\uc2a4\uba85\uc744 `ncds-editor-container`\ub85c \ubcc0\uacbd\ud558\uc600\uc2b5\ub2c8\ub2e4."},{"id":"release-note-editor-0.1.0","metadata":{"permalink":"/design-system/ncds-admin/releases/editor/release-note-editor-0.1.0","source":"@site/blog-editor/v0.1.0.md","title":"v1.0.0","description":"Editor \ub9b4\ub9ac\uc988 \ub178\ud2b8 (v0.1.0)","date":"2024-01-28T00:00:00.000Z","tags":[{"inline":false,"label":"Editor","permalink":"/design-system/ncds-admin/releases/editor/tags/editor","description":"Editor tag description"},{"inline":false,"label":"Feature","permalink":"/design-system/ncds-admin/releases/editor/tags/feature","description":"New feature tag description"}],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"release-note-editor-0.1.0","title":"v1.0.0","date":"2024-01-28T00:00:00.000Z","tags":["editor","feature"]},"unlisted":false,"prevItem":{"title":"v0.2.0","permalink":"/design-system/ncds-admin/releases/editor/release-note-editor-0.2.0"}},"content":"## Editor \ub9b4\ub9ac\uc988 \ub178\ud2b8 (v0.1.0)\\n\\n### \uc2e0\uaddc \uae30\ub2a5\\n\\n- **[\ud14d\uc2a4\ud2b8 \uc5d0\ub514\ud130](/docs/editor)** \uae30\ubcf8 \uae30\ub2a5\uc744 \ucd94\uac00\ud558\uc600\uc2b5\ub2c8\ub2e4.\\n- \uae30\ubcf8\uc801\uc778 \ud14d\uc2a4\ud2b8 \ud3b8\uc9d1 \uae30\ub2a5\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n### \ubb38\uc11c\\n\\n- Editor\uc758 **[\uc18c\uac1c \ubc0f \uc0ac\uc6a9\ubc29\ubc95](/docs/editor)** \ubb38\uc11c\ub97c \ucd94\uac00\ud558\uc600\uc2b5\ub2c8\ub2e4."}]}}')}}]);